const WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();

function parseDate(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.getTime();
}

const weekItems = [];
for (const item of items) {
  const data = item.json;
  const ms = parseDate(data.date || data.publishedAt || data.createdAt);
  if (ms !== null && now - ms > WINDOW_MS) continue;
  weekItems.push({
    title: data.title || '',
    url: data.url || '',
    category: data.category || 'autre',
    score: Number(data.score) || 0,
    summary: data.summary || '',
    source: data.source || '',
    subreddit: data.subreddit || '',
  });
}

weekItems.sort((a, b) => b.score - a.score);

const d = new Date();
const onejan = new Date(d.getFullYear(), 0, 1);
const weekNum = Math.ceil((((d - onejan) / 86400000) + onejan.getDay() + 1) / 7);
const year = d.getFullYear();

const listText = weekItems.length
  ? weekItems.map((it, i) => (
      (i + 1) + '. [' + it.score + '/10] ' + it.title + ' | ' + it.category + ' | ' + it.source
      + '\n   URL: ' + it.url
      + '\n   Resume: ' + it.summary
    )).join('\n')
  : 'Aucun item sur les 7 derniers jours.';

const SYSTEM_PROMPT = `Tu es le stratège de veille de Myrak.\n\nContexte Myrak :\n- Automatisation de process métiers + IA / agents pour freelances et PME.\n\nGénère un récap Slack en français, format mrkdwn Slack (liens <url|titre>), STRICTEMENT structuré ainsi :\n\n🧭 Veille Myrak – Semaine ${weekNum} / ${year}\n\n🔥 Top 5 de la semaine\n1. <url|Titre> – catégorie – Résumé (2 phrases).\n...\n\n📈 Tendances repérées\n- Observation 1 (2–3 phrases).\n- Observation 2 (2–3 phrases).\n- Observation 3 (2–3 phrases).\n\n💡 Idées pour Myrak\n- Offre / package possible : ...\n- Sujet de contenu / post : ...\n- Autre idée actionnable : ...\n\nRègles :\n- Pas d'introduction hors structure. Pas de JSON. Texte Slack prêt à poster.`;

const userMessage = 'Semaine ' + weekNum + '/' + year + ' — ' + weekItems.length + ' items:\n\n' + listText;

return [{
  json: {
    weekNum,
    year,
    itemCount: weekItems.length,
    items: weekItems,
    openRouterBody: {
      model: 'meta-llama/llama-3.3-70b-instruct:free',
      temperature: 0.4,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userMessage },
      ],
    },
  },
}];

const raw = items[0].json;
let text = '';
if (raw.choices && raw.choices[0]?.message?.content) {
  text = String(raw.choices[0].message.content);
} else if (typeof raw.text === 'string') {
  text = raw.text;
} else if (typeof raw.content === 'string') {
  text = raw.content;
} else {
  text = String(raw.slackMessage || raw.message || '');
}
text = String(text || '').trim();
if (!text) {
  text = '_Weekly Recap: aucun contenu genere._';
}
return [{ json: { slackMessage: text } }];
